SELECT /* getReportList */ A.REPT_NUMB , A.USER_NUMB , A.BOOK_NUMB , A.LANG_CODE , A.REPT_STAT , FN_GET_CODE_NAME(#{codeReadStat}, A.REPT_STAT, NULL, #{languageCode}) AS REPT_STAT_NAME , A.REPT_STDT , A.REPT_ENDT , A.REPT_GRDE , A.REPT_COLR , FN_GET_CODE_NAME(#{codeBookColr}, A.REPT_COLR, NULL, #{languageCode}) AS REPT_COLR_NAME , A.PUBC_YSNO , FN_GET_CODE_NAME(#{codeCommYsno}, A.PUBC_YSNO, #{optPubcYsno}, #{languageCode}) AS PUBC_YSNO_NAME , A.REPT_CNTN , B.BOOK_TITL , B.BOOK_CVIM , CASE WHEN A.REPT_STAT = #{reptStat} THEN #{commYes} ELSE #{commNo} END AS READING_YN FROM TM_REPORT A LEFT JOIN TM_BKINFO B ON A.BOOK_NUMB = B.BOOK_NUMB WHERE A.USER_NUMB = #{userNumb}
AND ( LOWER(B.BOOK_TITL) LIKE LOWER(#{bookKeywordLike}) OR LOWER(B.BOOK_ATHR) LIKE LOWER(#{bookKeywordLike}) )
ORDER BY A.REPT_STDT DESC, A.REPT_NUMB DESC
ORDER BY CAST(A.REPT_GRDE AS UNSIGNED) DESC, A.REPT_ENDT DESC, A.REPT_NUMB DESC
ORDER BY A.REPT_ENDT DESC, A.REPT_NUMB DESC
LIMIT #{pageOffset}, #{pageLimit}

WITH REPORTBASE AS ( SELECT A.REPT_ENDT , DATE_FORMAT(STR_TO_DATE(A.REPT_ENDT, '%Y-%m-%d'), '%x%v') AS WEEK_GOAL_DATE , DATE_FORMAT(STR_TO_DATE(A.REPT_ENDT, '%Y-%m-%d'), '%Y%m') AS MONTH_GOAL_DATE , CONCAT(DATE_FORMAT(STR_TO_DATE(A.REPT_ENDT, '%Y-%m-%d'), '%Y'), '00') AS YEAR_GOAL_DATE FROM TM_REPORT A WHERE A.USER_NUMB = #{userNumb} AND A.REPT_STAT = #{doneStat} AND A.REPT_ENDT IS NOT NULL
AND A.PUBC_YSNO = #{pubcYsno}
) , PERIODCNT AS ( SELECT COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{currentWeekStart} AND A.REPT_ENDT < #{nextWeekStart} THEN 1 ELSE 0 END), 0) AS CURRENT_WEEK_COUNT , COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{previousWeekStart} AND A.REPT_ENDT < #{currentWeekStart} THEN 1 ELSE 0 END), 0) AS PREVIOUS_WEEK_COUNT , COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{currentMonthStart} AND A.REPT_ENDT < #{nextMonthStart} THEN 1 ELSE 0 END), 0) AS CURRENT_MONTH_COUNT , COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{previousMonthStart} AND A.REPT_ENDT < #{currentMonthStart} THEN 1 ELSE 0 END), 0) AS PREVIOUS_MONTH_COUNT , COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{currentYearStart} AND A.REPT_ENDT < #{nextYearStart} THEN 1 ELSE 0 END), 0) AS CURRENT_YEAR_COUNT , COALESCE(SUM(CASE WHEN A.REPT_ENDT >= #{previousYearStart} AND A.REPT_ENDT < #{currentYearStart} THEN 1 ELSE 0 END), 0) AS PREVIOUS_YEAR_COUNT FROM REPORTBASE A ) , REPORTGOAL AS ( SELECT A.GOAL_TYPE , A.GOAL_DATE , COUNT(*) AS DONE_CNT FROM ( SELECT #{weekGoalType} AS GOAL_TYPE , A.WEEK_GOAL_DATE AS GOAL_DATE FROM REPORTBASE A UNION ALL SELECT #{monthGoalType} AS GOAL_TYPE , A.MONTH_GOAL_DATE AS GOAL_DATE FROM REPORTBASE A UNION ALL SELECT #{yearGoalType} AS GOAL_TYPE , A.YEAR_GOAL_DATE AS GOAL_DATE FROM REPORTBASE A ) A GROUP BY A.GOAL_TYPE , A.GOAL_DATE ) , GOALSUMMARY AS ( SELECT MAX(CASE WHEN G.GOAL_TYPE = #{weekGoalType} AND G.GOAL_DATE = #{currentWeekGoalDate} THEN G.GOAL_CNTT END) AS WEEK_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{weekGoalType} AND G.GOAL_DATE = #{previousWeekGoalDate} THEN G.GOAL_CNTT END) AS PREVIOUS_WEEK_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{monthGoalType} AND G.GOAL_DATE = #{currentMonthGoalDate} THEN G.GOAL_CNTT END) AS MONTH_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{monthGoalType} AND G.GOAL_DATE = #{previousMonthGoalDate} THEN G.GOAL_CNTT END) AS PREVIOUS_MONTH_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{yearGoalType} AND G.GOAL_DATE = #{currentYearGoalDate} THEN G.GOAL_CNTT END) AS YEAR_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{yearGoalType} AND G.GOAL_DATE = #{previousYearGoalDate} THEN G.GOAL_CNTT END) AS PREVIOUS_YEAR_GOAL_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{weekGoalType} AND G.GOAL_DATE = #{currentWeekGoalDate} THEN COALESCE(G.UPDT_CNTT, 0) END) AS WEEK_GOAL_UPDT_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{monthGoalType} AND G.GOAL_DATE = #{currentMonthGoalDate} THEN COALESCE(G.UPDT_CNTT, 0) END) AS MONTH_GOAL_UPDT_CNT , MAX(CASE WHEN G.GOAL_TYPE = #{yearGoalType} AND G.GOAL_DATE = #{currentYearGoalDate} THEN COALESCE(G.UPDT_CNTT, 0) END) AS YEAR_GOAL_UPDT_CNT , COALESCE(SUM(CASE WHEN G.GOAL_TYPE = #{weekGoalType} AND G.GOAL_CNTT > 0 AND COALESCE(R.DONE_CNT, 0) >= G.GOAL_CNTT THEN 1 ELSE 0 END), 0) AS WEEK_GOAL_ACHV_CNT , COALESCE(SUM(CASE WHEN G.GOAL_TYPE = #{monthGoalType} AND G.GOAL_CNTT > 0 AND COALESCE(R.DONE_CNT, 0) >= G.GOAL_CNTT THEN 1 ELSE 0 END), 0) AS MONTH_GOAL_ACHV_CNT , COALESCE(SUM(CASE WHEN G.GOAL_TYPE = #{yearGoalType} AND G.GOAL_CNTT > 0 AND COALESCE(R.DONE_CNT, 0) >= G.GOAL_CNTT THEN 1 ELSE 0 END), 0) AS YEAR_GOAL_ACHV_CNT FROM TM_GOALXM G LEFT JOIN REPORTGOAL R ON G.GOAL_TYPE = R.GOAL_TYPE AND G.GOAL_DATE = R.GOAL_DATE WHERE G.USER_NUMB = #{userNumb} ) SELECT /* getReadingSummary */ P.CURRENT_WEEK_COUNT , P.PREVIOUS_WEEK_COUNT , P.CURRENT_MONTH_COUNT , P.PREVIOUS_MONTH_COUNT , P.CURRENT_YEAR_COUNT , P.PREVIOUS_YEAR_COUNT , G.WEEK_GOAL_CNT , G.PREVIOUS_WEEK_GOAL_CNT , G.MONTH_GOAL_CNT , G.PREVIOUS_MONTH_GOAL_CNT , G.YEAR_GOAL_CNT , G.PREVIOUS_YEAR_GOAL_CNT , G.WEEK_GOAL_UPDT_CNT , G.MONTH_GOAL_UPDT_CNT , G.YEAR_GOAL_UPDT_CNT , G.WEEK_GOAL_ACHV_CNT , G.MONTH_GOAL_ACHV_CNT , G.YEAR_GOAL_ACHV_CNT FROM PERIODCNT P CROSS JOIN GOALSUMMARY G

   SELECT /* getReadingSummaryList */
          A.REPT_NUMB
        , A.USER_NUMB
        , A.BOOK_NUMB
        , A.LANG_CODE
        , A.REPT_STAT
        , A.REPT_STDT
        , A.REPT_ENDT
        , A.REPT_GRDE
        , A.PUBC_YSNO
        , REGEXP_REPLACE(B.BOOK_TITL, '[[:space:]]*[(][^)]*[)][[:space:]]*$', '') AS BOOK_TITL
        , B.BOOK_ATHR
        , B.BOOK_CVIM
        , B.BOOK_ISBN
     FROM TM_REPORT A
LEFT JOIN TM_BKINFO B
       ON A.BOOK_NUMB = B.BOOK_NUMB
    WHERE A.USER_NUMB = #{userNumb}

      AND A.PUBC_YSNO = #{pubcYsno}

      AND (   A.REPT_STAT = #{readStat}
           OR (    A.REPT_STAT = #{doneStat}
               AND A.REPT_ENDT >= #{currentYearStart}
               AND A.REPT_ENDT < #{nextYearStart}
              )
          )
 ORDER BY CASE WHEN A.REPT_STAT = #{readStat}
                    THEN 0
               ELSE 1
           END
        , CASE WHEN A.REPT_STAT = #{readStat}
                    THEN A.REPT_ENDT
           END ASC
        , CASE WHEN A.REPT_STAT = #{doneStat}
                    THEN A.REPT_ENDT
           END DESC
        , A.REPT_NUMB DESC

SELECT /* getReadingGoalDtl */
       G.USER_NUMB
     , G.GOAL_DATE
     , G.GOAL_TYPE
     , G.GOAL_CNTT AS GOAL_CNT
     , COALESCE(G.UPDT_CNTT, 0) AS UPDT_CNTT
  FROM TM_GOALXM G
 WHERE G.USER_NUMB = #{userNumb}
   AND G.GOAL_DATE = #{goalDate}
   AND G.GOAL_TYPE = #{goalType}



SELECT /* getReportLikeDtl */
       R.USER_NUMB AS TARGET_USER_NUMB
     , R.LKAL_YSNO AS LIKE_ALIM_YSNO
  FROM TM_REPORT R
 WHERE R.REPT_NUMB = #{tagtNumb}
   AND (
       R.USER_NUMB = #{userNumb}
    OR (    R.PUBC_YSNO = #{commYes}
        AND R.REPT_STAT != #{reptStatRead}
       )
   )




    SELECT /* getReportTrnsSource */
           P.REPT_NUMB
         , P.LANG_CODE AS SOURCE_LANG_CODE
         , P.REPT_CNTN AS SOURCE_CONTENT
      FROM TM_REPORT P
INNER JOIN TM_USERXM U
        ON U.USER_NUMB = P.USER_NUMB
       AND U.USER_STAT = #{userStatActive}
INNER JOIN TM_USERXM A
        ON A.USER_NUMB = #{userNumb}
       AND A.USER_STAT = #{userStatActive}
     WHERE P.REPT_NUMB = #{reptNumb}
       AND P.PUBC_YSNO = #{commYes}
       AND P.REPT_STAT != #{reptStatRead}
       AND NOT EXISTS (
           SELECT 1
             FROM TB_USBLOC B
            WHERE (B.USER_NUMB = #{userNumb} AND B.BLOC_NUMB = P.USER_NUMB)
               OR (B.USER_NUMB = P.USER_NUMB AND B.BLOC_NUMB = #{userNumb})
       )
       FOR UPDATE

