/* setReportTrns */
INSERT INTO TB_REPTRN (
            REPT_NUMB
          , LANG_CODE
          , ORIG_HASH
          , TRNS_CNTN
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{reptNumb}
          , #{langCode}
          , #{origHash}
          , #{trnsCntn}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)
ON DUPLICATE KEY UPDATE
       ORIG_HASH = VALUES(ORIG_HASH)
     , TRNS_CNTN = VALUES(TRNS_CNTN)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)

/* setReport */
INSERT INTO TM_REPORT (
            USER_NUMB
          , BOOK_NUMB
          , LANG_CODE
          , REPT_STAT
          , REPT_STDT
          , REPT_ENDT
          , REPT_GRDE
          , REPT_COLR
          , REPT_CNTN
          , PUBC_YSNO
          , LKAL_YSNO
          , RPAL_YSNO
          , PUBC_DATE
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{bookNumb}
          , #{langCode}
          , #{reptStat}
          , #{reptStdt}
          , #{reptEndt}
          , #{reptGrde}
          , #{reptColr}
          , #{reptCntn}
          , #{pubcYsno}
          , #{likeAlimYsno}
          , #{replyAlimYsno}
          , CASE WHEN #{pubcYsno} = 'Y' AND #{reptStat} != 'READ'
                      THEN CURRENT_TIMESTAMP(6)
                 ELSE NULL
            END
          , CURRENT_TIMESTAMP
          , CURRENT_TIMESTAMP
)

mapper.update:

UPDATE /* uptReport */
       TM_REPORT
   SET LANG_CODE = #{langCode}
     , REPT_STAT = #{reptStat}
     , REPT_STDT = CASE WHEN EXISTS ( SELECT 1
                                           FROM TB_CLPART PART
                                     INNER JOIN TM_CLRNDX ROUNDX
                                             ON ROUNDX.CLUB_NUMB = PART.CLUB_NUMB
                                            AND ROUNDX.ROND_NUMB = PART.ROND_NUMB
                                          WHERE PART.REPT_NUMB = TM_REPORT.REPT_NUMB
                                            AND ROUNDX.ROND_STAT = #{roundReading}
                                            AND CURRENT_DATE BETWEEN DATE(ROUNDX.GOAL_STDT) AND DATE(ROUNDX.GOAL_ENDT)
                                       )
                            THEN REPT_STDT
                            ELSE #{reptStdt}
                        END
     , REPT_ENDT = #{reptEndt}
     , REPT_GRDE = #{reptGrde}
     , REPT_COLR = #{reptColr}
     , REPT_CNTN = #{reptCntn}
     , PUBC_YSNO = #{pubcYsno}
     , PUBC_DATE = CASE WHEN PUBC_DATE IS NULL
                              AND #{pubcYsno} = 'Y'
                              AND #{reptStat} != 'READ'
                             THEN CURRENT_TIMESTAMP(6)
                        ELSE PUBC_DATE
                   END
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}
   AND SHA2(CONCAT_WS('|'
            , COALESCE(LANG_CODE, '')
            , COALESCE(REPT_STAT, '')
            , COALESCE(REPT_STDT, '')
            , COALESCE(REPT_ENDT, '')
            , COALESCE(REPT_GRDE, '')
            , COALESCE(REPT_COLR, '')
            , COALESCE(PUBC_YSNO, '')
            , COALESCE(REPT_CNTN, '')
       ), 256) = #{editVersion}

UPDATE /* uptLikeAlim */
       TM_REPORT
   SET LKAL_YSNO = #{useYsno}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}

UPDATE /* uptReplyAlim */
       TM_REPORT
   SET RPAL_YSNO = #{useYsno}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}

UPDATE /* uptReptStatusGrade */
       TM_REPORT

       REPT_STAT = #{reptStat}
     , REPT_GRDE = #{reptGrde}
     , PUBC_YSNO = #{pubcYsno}
     , PUBC_DATE = CASE WHEN PUBC_DATE IS NULL
                              AND #{pubcYsno} = 'Y'
                              AND #{reptStat} != 'READ'
                             THEN CURRENT_TIMESTAMP(6)
                        ELSE PUBC_DATE
                   END

     , REPT_ENDT = #{reptEndt}

     , UPDT_DATE = CURRENT_TIMESTAMP

 WHERE REPT_NUMB = #{reptNumb}
   AND USER_NUMB = #{userNumb}

